create unique index if not exists collector_alerts_source_open_unique_idx on public.collector_alerts(source_table,source_id,alert_type) where status='Open' and source_id is not null and btrim(source_id)<>'';
create unique index if not exists follow_ups_broken_source_unique_idx on public.follow_ups(account_id,follow_up_type,due_date) where status='Open' and follow_up_type='Broken Promise Follow-Up';
-- Atomic broken-promise transitions keep payment/account/follow-up/alert state together.
create or replace function public.cpcm_flag_broken_plan_payment(target_payment_id uuid, actor_email text default null) returns jsonb language plpgsql security invoker set search_path=public as $$ declare p public.payment_plan_payments%rowtype; aid uuid; pid uuid; assignee text; begin select * into p from public.payment_plan_payments where id=target_payment_id for update; if not found then raise exception 'Scheduled payment not found'; end if; if coalesce(p.due_date,p.scheduled_date,p.payment_date)>=current_date or lower(coalesce(p.status,'')) in ('paid','cancelled') or coalesce(p.amount_paid,0)>=coalesce(p.amount_due,p.payment_amount,p.amount,0) then return jsonb_build_object('ok',true,'flagged',false); end if; aid:=p.account_id; pid:=coalesce(p.plan_id,p.payment_plan_id); update public.payment_plan_payments set status='Broken Promise',updated_at=now() where id=p.id; if pid is not null then update public.payment_plans set status='Broken Promise',updated_at=now() where id=pid; end if; update public.accounts set status='Broken Promise',disposition='Broken Promise',updated_at=now() where id=aid returning assigned_to_email into assignee; insert into public.follow_ups(account_id,follow_up_type,due_date,status,assigned_to_email,reason,notes,created_by_email) values(aid,'Broken Promise Follow-Up',current_date,'Open',coalesce(assignee,actor_email,''),'Missed payment promise','Automatically created from broken promise automation.',coalesce(actor_email,'system')) on conflict (account_id,follow_up_type,due_date) where status='Open' and follow_up_type='Broken Promise Follow-Up' do nothing; insert into public.collector_alerts(account_id,alert_type,severity,title,message,due_date,status,assigned_to_email,created_by_email,source_table,source_id) values(aid,'Broken Promise','critical','Broken payment plan promise','Missed scheduled payment requires follow-up.',current_date,'Open',coalesce(assignee,actor_email,''),coalesce(actor_email,'system'),'payment_plan_payments',p.id::text) on conflict (source_table,source_id,alert_type) where status='Open' and source_id is not null and btrim(source_id)<>'' do nothing; return jsonb_build_object('ok',true,'flagged',true,'account_id',aid); end; $$;
create or replace function public.cpcm_flag_broken_manual_promise(target_promise_id uuid, actor_email text default null) returns jsonb language plpgsql security invoker set search_path=public as $$ declare p public.payment_promises%rowtype; assignee text; amt numeric; begin select * into p from public.payment_promises where id=target_promise_id for update; if not found then raise exception 'Payment promise not found'; end if; if p.due_date>=current_date or lower(coalesce(p.status,'')) in ('paid','completed','settled','canceled','cancelled','broken promise') or coalesce(p.paid_amount,0)>=coalesce(p.payment_amount,0) then return jsonb_build_object('ok',true,'flagged',false); end if; amt:=greatest(coalesce(p.payment_amount,0)-coalesce(p.paid_amount,0),0); update public.payment_promises set status='Broken Promise',admin_note='Auto-flagged missed payment promise due '||p.due_date::text||'.',processed_by_email=coalesce(actor_email,processed_by_email),processed_at=now(),updated_at=now() where id=p.id; update public.accounts set status='Broken Promise',disposition='Broken Promise',updated_at=now() where id=p.account_id returning assigned_to_email into assignee; insert into public.follow_ups(account_id,follow_up_type,due_date,status,assigned_to_email,reason,notes,created_by_email) values(p.account_id,'Broken Promise Follow-Up',current_date,'Open',coalesce(assignee,p.employee_email,actor_email,''),'Missed manual payment promise','Automatically created from Promise Automation.',coalesce(actor_email,'system')) on conflict (account_id,follow_up_type,due_date) where status='Open' and follow_up_type='Broken Promise Follow-Up' do nothing; insert into public.collector_alerts(account_id,alert_type,severity,title,message,due_date,status,assigned_to_email,created_by_email,source_table,source_id) values(p.account_id,'Broken Promise','critical','Broken promise needs follow-up','Missed manual payment promise of '||amt::text||' requires follow-up.',current_date,'Open',coalesce(assignee,p.employee_email,actor_email,''),coalesce(actor_email,'system'),'payment_promises',p.id::text) on conflict (source_table,source_id,alert_type) where status='Open' and source_id is not null and btrim(source_id)<>'' do nothing; return jsonb_build_object('ok',true,'flagged',true,'account_id',p.account_id,'amount',amt); end; $$;
